+        rentVal = randInt(prng, 52, 78) * 100_000;
+        staffFte = Number(randRange(prng, 1.0, 1.8).toFixed(1));
+        menuTier = 2;
+        avgTicketKrw = randInt(prng, 48, 56) * 100;
+        makeTimeSec = randInt(prng, 85, 115);
